mapper.select:
select * from TBL_STAFF where REALNAME = #{staffName}

    and ORGID in (SELECT ORGID from TBL_ORGANIZATION where FATHERORGID=#{orgid} OR ORGID=#{orgid})

and ROWNUM=1 order by STAFFID desc

select a.STAFFID as staffId,a.USERNAME as userName,a.realName as REALNAME,a.MIBLEPHONE as miblePhone,a.FIXEDPHONE as fixedPhone,a.EMAIL,a.MEMO, b.ORGNAME as orgname,a.ONDUTYSTATUS as onDutyStatus from TBL_STAFF a left join TBL_ORGANIZATION b on a.ORGID = b.ORGID where 1=1
and a.ONDUTYSTATUS = #{param.onDutyStatus}
and a.REALNAME like concat('%',concat(#{param.realName},'%'))
and a.STAFFID in
#{item}
order by a.orgid desc
